CREATE FUNCTION public.pipeline_candidate_action(token text,command text,payload jsonb DEFAULT '{}') RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE a assessment_attempts;b assessment_batteries;c assessment_campaigns;i jsonb;section text;deadline timestamptz;mins integer;items jsonb;sections jsonb;ord jsonb;opts jsonb;answer text;keys text[];n integer;BEGIN PERFORM pg_advisory_xact_lock(811112026);SELECT * INTO a FROM assessment_attempts WHERE token_hash=token FOR UPDATE;IF a.id IS NULL OR a.revoked OR a.purged_at IS NOT NULL OR a.expires_at<=now() THEN RAISE EXCEPTION 'Invitation expired or unavailable';END IF;SELECT * INTO b FROM assessment_batteries WHERE id=a.battery_id;SELECT * INTO c FROM assessment_campaigns WHERE id=a.campaign_id;IF b.status<>'approved' OR (c.id IS NOT NULL AND (now()<c.opens_at OR now()>=c.closes_at)) THEN RAISE EXCEPTION 'Campaign is not open';END IF;
IF a.question_order='[]' THEN SELECT coalesce(jsonb_agg(value->>'id'),'[]') INTO ord FROM (SELECT value FROM jsonb_array_elements(b.payload->'items') WHERE value->>'status'='approved' AND NOT (value->>'practice')::boolean ORDER BY random()) q;opts:='{}';FOR i IN SELECT value FROM jsonb_array_elements(b.payload->'items') WHERE value->>'status'='approved' LOOP SELECT coalesce(jsonb_agg(idx),'[]') INTO items FROM (SELECT ordinality-1 idx FROM jsonb_array_elements(i->'options') WITH ORDINALITY ORDER BY random()) o;opts:=opts||jsonb_build_object(i->>'id',items);END LOOP;UPDATE assessment_attempts SET question_order=ord,option_order=opts WHERE id=a.id;a.question_order:=ord;a.option_order:=opts;END IF;
IF command NOT IN ('load','demographic') AND a.status IN ('submitted','scored') THEN RAISE EXCEPTION 'Responses already received';END IF;
IF command='accommodation' THEN IF a.status<>'invited' THEN RAISE EXCEPTION 'Request before starting';END IF;IF payload->>'type' NOT IN ('extra_time','screen_reader','other') THEN RAISE EXCEPTION 'Choose an accommodation type';END IF;UPDATE assessment_attempts SET accommodation_request=left((payload->>'type')||': '||coalesce(payload->>'request',''),2000),accommodation_status='pending' WHERE id=a.id;END IF;
IF command='demographic' THEN INSERT INTO assessment_demographics(attempt_id,group_label) VALUES(a.id,left(coalesce(payload->>'group',''),100)) ON CONFLICT(attempt_id) DO UPDATE SET group_label=excluded.group_label;END IF;
IF command='practice' THEN section:=payload->>'section';IF NOT EXISTS(SELECT 1 FROM jsonb_array_elements(b.payload->'items') WHERE value->>'section'=section) THEN RAISE EXCEPTION 'Unknown section';END IF;UPDATE assessment_attempts SET practice_completed=practice_completed||jsonb_build_array(section) WHERE id=a.id AND NOT practice_completed ? section;END IF;
IF command='start' THEN section:=payload->>'section';IF a.completed_sections ? section THEN RAISE EXCEPTION 'Section already completed';END IF;IF a.accommodation_status='pending' THEN RAISE EXCEPTION 'HR is reviewing your accommodation request';END IF;IF NOT a.practice_completed ? section THEN RAISE EXCEPTION 'Complete the practice item first';END IF;IF a.privacy_accepted_at IS NULL AND coalesce((payload->>'privacy_accepted')::boolean,false) IS NOT TRUE THEN RAISE EXCEPTION 'Consent required';END IF;IF a.current_section IS NOT NULL AND a.current_section<>section THEN RAISE EXCEPTION 'Finish current section first';END IF;SELECT sum((value->>'minutes')::integer) INTO mins FROM jsonb_array_elements(b.payload->'items') WHERE value->>'section'=section AND value->>'status'='approved' AND NOT (value->>'practice')::boolean;IF mins IS NULL THEN RAISE EXCEPTION 'Unknown section';END IF;deadline:=coalesce((a.section_deadlines->>section)::timestamptz,now()+make_interval(mins=>mins+a.extra_minutes));UPDATE assessment_attempts SET privacy_accepted_at=coalesce(privacy_accepted_at,now()),started_at=coalesce(started_at,now()),status='in_progress',current_section=section,section_deadlines=section_deadlines||jsonb_build_object(section,deadline) WHERE id=a.id;END IF;
IF command='save' THEN IF a.status<>'in_progress' OR a.current_section IS NULL OR (a.section_deadlines->>a.current_section)::timestamptz<=now() THEN RAISE EXCEPTION 'Section time has ended';END IF;FOR i IN SELECT value FROM jsonb_array_elements(b.payload->'items') WHERE value->>'section'=a.current_section AND value->>'status'='approved' AND NOT (value->>'practice')::boolean LOOP IF payload->'answers' ? (i->>'id') THEN answer:=left(payload->'answers'->>(i->>'id'),12000);IF i->>'method'='sjt' AND answer<>'' AND answer !~ '^[1-5],[1-5],[1-5],[1-5]$' THEN RAISE EXCEPTION 'Rate every SJT option';END IF;IF i->>'method'<>'sjt' AND jsonb_array_length(i->'options')>0 AND answer<>'' AND (answer !~ '^\d+$' OR answer::integer>=jsonb_array_length(i->'options')) THEN RAISE EXCEPTION 'Invalid option';END IF;INSERT INTO pipeline_responses(attempt_id,item_id,answer,time_seconds) VALUES(a.id,i->>'id',answer,least(greatest(coalesce((payload->'times'->>(i->>'id'))::integer,0),0),86400)) ON CONFLICT(attempt_id,item_id) DO UPDATE SET answer=excluded.answer,time_seconds=greatest(pipeline_responses.time_seconds,excluded.time_seconds),updated_at=now();a.answers:=a.answers||jsonb_build_object(i->>'id',answer);END IF;END LOOP;UPDATE assessment_attempts SET answers=a.answers WHERE id=a.id;END IF;
IF command='finish_section' THEN IF a.current_section IS NULL THEN RAISE EXCEPTION 'No active section';END IF;UPDATE assessment_attempts SET completed_sections=completed_sections||jsonb_build_array(current_section),section_times=section_times||jsonb_build_object(current_section,now()),current_section=NULL WHERE id=a.id;END IF;
IF command='submit' THEN IF EXISTS(SELECT 1 FROM jsonb_array_elements(b.payload->'items') WHERE value->>'status'='approved' AND NOT (value->>'practice')::boolean AND NOT a.completed_sections ? (value->>'section')) THEN RAISE EXCEPTION 'Finish all sections before submission';END IF;UPDATE assessment_attempts SET status='submitted',submitted_at=now(),current_section=NULL WHERE id=a.id;PERFORM pipeline_recalculate(a.id);END IF;
SELECT * INTO a FROM assessment_attempts WHERE id=a.id;
SELECT jsonb_agg(jsonb_build_object('name',name,'minutes',minutes+a.extra_minutes,'count',cnt,'completed',a.completed_sections ? name,'practice_completed',a.practice_completed ? name)) INTO sections FROM (SELECT value->>'section' name,sum((value->>'minutes')::integer) minutes,count(*) cnt FROM jsonb_array_elements(b.payload->'items') WHERE value->>'status'='approved' AND NOT (value->>'practice')::boolean GROUP BY value->>'section') s;
SELECT coalesce(jsonb_agg((i.value-ARRAY['options','correct','key','explanation','approvals','task_ids','ksao_ids','rubric','incident_id'])||jsonb_build_object('options',(SELECT coalesce(jsonb_agg(jsonb_build_object('id',o.value::text,'label',i.value->'options'->>(o.value::text::integer))),'[]') FROM jsonb_array_elements(a.option_order->(i.value->>'id')) o)) ORDER BY array_position(ARRAY(SELECT jsonb_array_elements_text(a.question_order)),i.value->>'id')),'[]') INTO items FROM jsonb_array_elements(b.payload->'items') i WHERE i.value->>'status'='approved' AND ((i.value->>'practice')::boolean OR (i.value->>'section'=a.current_section AND a.status='in_progress'));
RETURN jsonb_build_object('id',a.id,'name',a.name,'title',b.payload->>'title','organization',b.payload->>'organization','welcome_message',coalesce(c.welcome_message,''),'status',a.status,'expires_at',a.expires_at,'privacy_notice',a.privacy_notice,'privacy_accepted',a.privacy_accepted_at IS NOT NULL,'items',items,'sections',sections,'answers',a.answers,'current_section',a.current_section,'deadlines',a.section_deadlines,'accommodation_request',a.accommodation_request,'accommodation_status',a.accommodation_status,'extra_minutes',a.extra_minutes,'alternate_format',a.alternate_format,'server_time',now(),'unanswered',(SELECT coalesce(jsonb_agg(value->>'title'),'[]') FROM jsonb_array_elements(b.payload->'items') WHERE value->>'status'='approved' AND NOT (value->>'practice')::boolean AND btrim(coalesce(a.answers->>(value->>'id'),''))=''));END $$;
REVOKE ALL ON FUNCTION pipeline_candidate_action(text,text,jsonb) FROM PUBLIC,anon,authenticated;GRANT EXECUTE ON FUNCTION pipeline_candidate_action(text,text,jsonb) TO service_role;
CREATE FUNCTION public.pipeline_accommodation(aid uuid,extra integer,format text,decision text) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE a assessment_attempts;BEGIN SELECT * INTO a FROM assessment_attempts WHERE id=aid;IF NOT org_can('campaigns',a.battery_id) OR a.status<>'invited' OR decision NOT IN ('approved','declined') OR extra NOT BETWEEN 0 AND 240 THEN RAISE EXCEPTION 'HR pre-start accommodation review required';END IF;UPDATE assessment_attempts SET extra_minutes=extra,alternate_format=format,accommodation_status=decision WHERE id=aid;RETURN true;END $$;
CREATE FUNCTION public.pipeline_server_accommodation(aid uuid,extra integer,format text,decision text,actor uuid) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF auth.role()<>'service_role' THEN RAISE EXCEPTION 'Server action required';END IF;PERFORM set_config('request.jwt.claims',jsonb_build_object('sub',actor,'role','authenticated')::text,true);PERFORM set_config('app.score_action',actor::text,true);RETURN pipeline_accommodation(aid,extra,format,decision);END $$;
REVOKE ALL ON FUNCTION pipeline_accommodation(uuid,integer,text,text),pipeline_server_accommodation(uuid,integer,text,text,uuid) FROM PUBLIC,anon,authenticated;GRANT EXECUTE ON FUNCTION pipeline_server_accommodation(uuid,integer,text,text,uuid) TO service_role;